import{_ as a,c as r,o as i,ag as n}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"E03 — Security and API boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"practice/engineering/e03.md","filePath":"practice/engineering/e03.md"}'),t={name:"practice/engineering/e03.md"};function s(o,e,c,d,l,p){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="e03-—-security-and-api-boundaries" tabindex="-1">E03 — Security and API boundaries <a class="header-anchor" href="#e03-—-security-and-api-boundaries" aria-label="Permalink to “E03 — Security and API boundaries”">​</a></h1><p><strong>Learner status: outstanding.</strong> Reuses P-330/P-331.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>HTTP, runtime validation and server-established identity. Follow <a href="./../../engineering/security.html">the reading guide</a>.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Implement one two-user protected read/write using the existing Node/Next contract. Choose cookie/CSRF or a separately designed token flow.</p><h2 id="observable-acceptance" tabindex="-1">Observable acceptance <a class="header-anchor" href="#observable-acceptance" aria-label="Permalink to “Observable acceptance”">​</a></h2><p>Foreign owner denied at the operation, stale version cannot overwrite, unsafe fields reject, safe errors/logs contain no private sentinel, storage/caches respect scope.</p><h2 id="failure-cases" tabindex="-1">Failure cases <a class="header-anchor" href="#failure-cases" aria-label="Permalink to “Failure cases”">​</a></h2><p>Anonymous/revoked/foreign actor, forged owner, malformed/oversize body, cross-origin mutation, uncertain write and private cache collision.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “Evidence”">​</a></h2><p>Safe HTTP/DB negative checks and threat→control→test map. Browser TLS/cookie/CSP/provider checks need actual declared environments. Retain source/tool versions, expected versus actual, failure→fix→retest and open verification gaps. Author checks never complete this increment.</p>',12)])])}const f=a(t,[["render",s]]);export{u as __pageData,f as default};
